    if(session.part==='drums'){const candidate=session.candidates.drums,pads=[[36,'Kick'],[38,'Snare'],[42,'Closed Hat'],[46,'Open Hat']];return`<section class="music-part-workflow" aria-labelledby="partWorkflowTitle"><div class="music-section-heading"><div><p class="music-kicker">Drums workflow</p><h2 id="partWorkflowTitle">ドラム制作</h2></div><p>GM MIDIノート番号を保ったまま、パターン候補と共通エディターを同じDrumsトラックへ接続します。</p></div><div class="music-generation-actions"><button class="music-primary" onclick="MusicStudio.editorGenerateCandidate('basic')">基本パターン候補</button><button class="music-secondary" onclick="MusicStudio.editorGenerateCandidate('alternate')">別パターン候補</button>${candidate?`<button class="music-secondary" onclick="MusicStudio.editorApplyCandidate()">「${escapeHtml(candidate.label)}」を採用（${candidate.notes.length}ノート）</button>`:''}</div><div class="music-drum-pads" role="group" aria-label="ドラム入力">${pads.map(([pitch,label])=>`<button class="music-secondary" onclick="MusicStudio.editorDrumInput(${pitch})">${label}<small>Note ${pitch}</small></button>`).join('')}</div>${candidate?'<p class="music-help">候補を確認中です。「採用」を押すまで現在のDrumsノートは変更されません。</p>':'<p class="music-help">候補生成は端末内の簡易パターンです。高度なAI生成は未接続です。</p>'}${rangeTools(session)}</section>`}
